import fs from 'node:fs/promises';import assert from 'node:assert/strict';import crypto from 'node:crypto';
const dir='data/research/margin3-market-volume-20261107',read=async p=>JSON.parse(await fs.readFile(p)),save=async(p,x)=>fs.writeFile(p,JSON.stringify(x,null,2)),x=await read(dir+'/results.json'),v=await read(dir+'/validation.json'),S=300000;
const raw=new Map();for(const [sym,h]of Object.entries(v.rawHashes)){const b=await fs.readFile(dir+'/raw/'+sym+'.json');assert.equal(crypto.createHash('sha256').update(b).digest('hex'),h);raw.set(sym,new Map(JSON.parse(b).price.map(a=>[+a[0],a])));}
const near=(a,b)=>assert.ok(Math.abs(a-b)<1e-8,JSON.stringify({a,b}));
let checked=0;
for(const r of x.records)for(const mode of ['preorder','atFill']){const f=r.market[mode];if(f.status!=='OK')continue;assert.equal(f.at,mode==='preorder'?r.submittedAt:Date.parse(r.filledAt));const end=Math.floor((f.at-5000)/S)*S;const p=[],b=[];for(let i=49;i>=1;i--){p.push(raw.get(r.symbol).get(end-i*S));b.push(raw.get('BTCUSDT').get(end-i*S));}assert.ok([...p,...b].every(a=>a&&+a[6]+5000<=f.at));let q=0,t=0,old=0;for(let i=46;i<49;i++){q+=+p[i][7];t+=+p[i][10];}for(let i=26;i<46;i++)old+=+p[i][7];near(f.volumeRatio,q/(old/20*3));near(f.takerBuyPct,t/q*100);for(const [key,a,k]of [['coin15m',p,3],['coin1h',p,12],['coin4h',p,48],['btc1h',b,12],['btc4h',b,48]])near(f[key],(+a[48][4]/+a[48-k][4]-1)*100);near(r.realizedRoePct,r.netRealizedPnlUsdt/3*100);checked++;}
function flags(r,m){const f=r.market[m],s=r.direction==='SHORT'?-1:1,v=f.volumeRatio>=1.5,flow=(s===1?f.takerBuyPct:100-f.takerBuyPct)>=55,c=f.coin1h*s>0,b=f.btc1h*s>0;return{VOLUME:v,FLOW:flow,COIN_TREND:c,BTC_TREND:b,FLOW_VOLUME:v&&flow,CONFLUENCE:v&&flow&&c&&b};}
let seed=836729;function rand(){seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296;}
const avg=rs=>rs.reduce((s,r)=>s+r.realizedRoePct,0)/rs.length;
function boot(rs,key,groupKey){const groups=new Map();for(const r of rs){const g=groupKey(r);if(!groups.has(g))groups.set(g,[]);groups.get(g).push(r);}const buckets=[...groups.values()],diff=[];for(let j=0;j<2000;j++){const sample=[];for(let i=0;i<buckets.length;i++)sample.push(...buckets[Math.floor(rand()*buckets.length)]);const kept=sample.filter(r=>flags(r,'preorder')[key]);if(kept.length)diff.push(avg(kept)-avg(sample));}diff.sort((a,b)=>a-b);return{clusters:buckets.length,validReplicates:diff.length,deltaMeanRoe95:diff.length?[diff[Math.floor(diff.length*.025)],diff[Math.floor(diff.length*.975)]]:null};}
const checks=[],ci={};for(const mode of ['preorder','atFill'])for(const side of ['LONG','SHORT']){const s=x.summary[mode][side],rs=x.records.filter(r=>r.direction===side&&r.market[mode].status==='OK'&&Number.isFinite(r.market[mode].volumeRatio)&&Number.isFinite(r.market[mode].takerBuyPct));assert.equal(rs.length,s.baseline.n);if(rs.length)near(avg(rs),s.baseline.meanRoe);for(const key of Object.keys(s.filters)){const kept=rs.filter(r=>flags(r,mode)[key]),test=kept.filter(r=>r.market[mode].at>=s.split);assert.equal(kept.length,s.filters[key].kept.n);assert.equal(test.length,s.filters[key].test.n);if(kept.length)near(avg(kept),s.filters[key].kept.meanRoe);}checks.push({mode,side,n:rs.length});}
const rs=x.records.filter(r=>r.direction==='SHORT'&&r.market.preorder.status==='OK'&&Number.isFinite(r.market.preorder.volumeRatio)&&Number.isFinite(r.market.preorder.takerBuyPct));for(const key of Object.keys(x.summary.preorder.SHORT.filters)){ci[key]={allByCoin:boot(rs,key,r=>r.symbol),allByDay:boot(rs,key,r=>new Date(r.submittedAt+7*3600000).toISOString().slice(0,10)),testByCoin:boot(rs.filter(r=>r.submittedAt>=x.summary.preorder.SHORT.split),key,r=>r.symbol)};}
await save(dir+'/uncertainty.json',{method:'Paired resampling of observed order groups; delta selected mean ROE minus same baseline. 2000 draws; fixed seed; nominal intervals NOT multiplicity-adjusted. No profitability probability claims.',ci});await save(dir+'/independent-validation.json',{status:'PASS',rawHashCount:raw.size,recomputedFeatureJoins:checked,checks,actualRoeEqualsNetDiv3:true,thresholdAndTestStatsIndependentlyRecomputed:true});console.log(JSON.stringify({checked,checks,ci}));

